def has_opt(root, target):
    if root is None: return False
    q = deque([(root, root.v)])
    while q:
        n, s = q.popleft()
        if n.l is None and n.r is None:
            if s == target: return True
            continue
        if n.l: q.append((n.l, s + n.l.v))
        if n.r: q.append((n.r, s + n.r.v))
